func fuzz() {
 ExprSyntaxProtocol {
  /// Whether any of the nodes in this expression involve compiler or feature
  /// checks.
  fileprivate var containsFeatureCheck: Bool {
    let visitor = FindFeatureCheckVisitor(viewMode: ./*c*/fixedUp)
    visitor.walk(self)
    return visitor.foundFeatureCheck}
}
}

